template <typename DisplayT>
void drawPikaFrame(DisplayT &display, uint8_t frame, int16_t x, int16_t y) {
  frame %= PIKA_FRAME_COUNT;
  for (uint8_t py = 0; py < PIKA_H; py++) {
    for (uint8_t px = 0; px < PIKA_W; px++) {
      uint16_t color = pgm_read_word(&pikaFrames[frame][py][px]);
      display.drawPixel(x + px, y + py, color);
    }
  }
}
